        }

        HostedProducerDiscovery<HostedProducerSite> parallel = Discover(workers);

        Assert.Equal(mode == "invalid-matrix" ? 1 : workers, parallel.AnalysisMetrics!.RootWorkers);

        AssertDiscoveryParity(serial, parallel);
    }

