                        public const string Owner = "owner";

                        public const string Unsupported = "unsupported";
                    }

                    public static class LongRunningOperationRecoveryRegistry
                    {
                        private static readonly LongRunningOperationRecoveryDescriptor[] Matrix =
                        [
