    [Theory]
    [InlineData("existing-null", true)]
    [InlineData("existing-overwritten-unknown", true)]
    [InlineData("conditional-null", true)]
    [InlineData("conditional-unknown", false)]
    [InlineData("missing-acquisition", false)]
    [InlineData("lookalike", false)]
    [InlineData("existing-reassigned", false)]
    [InlineData("existing-ref-escape", false)]
    [InlineData("out-var", true)]
    [InlineData("out-var-reassigned", false)]
    [InlineData("out-var-ref-escape", false)]
    public void ExplicitAdmissionCleanupRequiresExactCurrentLocalValue(
        string shape,
        bool exact)
    {
        string acquisition = shape switch
        {
            "existing-overwritten-unknown" => "IDisposable group = AdmissionCleanupInput.Unknown(); if (!lease.TryBeginExternalEffectGroup(out group)) return;",
            "conditional-unknown" => "IDisposable group = AdmissionCleanupInput.Unknown(); if (token.CanBeCanceled && !lease.TryBeginExternalEffectGroup(out group)) return;",
            "conditional-null" => "IDisposable group = null!; if (token.CanBeCanceled && !lease.TryBeginExternalEffectGroup(out group)) return;",
            "missing-acquisition" => "IDisposable group = AdmissionCleanupInput.Unknown();",
            "lookalike" => "IDisposable group = null!; if (!AdmissionCleanupInput.TryBeginExternalEffectGroup(out group)) return;",
            "out-var" or "out-var-reassigned" or "out-var-ref-escape" => "if (!lease.TryBeginExternalEffectGroup(out var group)) return;",
            _ => "IDisposable group = null!; if (!lease.TryBeginExternalEffectGroup(out group)) return;",
        };

        string mutation = shape switch
        {
            "existing-reassigned" or "out-var-reassigned" => "group = AdmissionCleanupInput.Unknown();",
            "existing-ref-escape" or "out-var-ref-escape" => "AdmissionCleanupInput.Replace(ref group);",
            _ => string.Empty,
        };

        string source = R2Source(
            AcquireWork.Replace("return Task.CompletedTask;", "return;", StringComparison.Ordinal)
                + acquisition
                + " try { " + mutation + " System.IO.File.Exists(\"admission-cleanup-control\"); }"
                + " finally { if (group is not null) group.Dispose(); }",
            "internal static class AdmissionCleanupInput { internal static extern IDisposable Unknown(); internal static extern void Replace(ref IDisposable value); internal static extern bool TryBeginExternalEffectGroup(out IDisposable group); }");

        CSharpCompilation compilation = Compile(source);

        Assert.Empty(compilation.GetDiagnostics().Where(static diagnostic =>
            diagnostic.Severity == DiagnosticSeverity.Error));

        HostedProducerDiscovery<HostedProducerSite> result = R2Discover(source);

        Assert.Single(result.Items, static site => site.Callee == "System.IO.File.Exists");

        Assert.Equal(
            exact,
            !result.Diagnostics.Any(static diagnostic =>
                diagnostic.Code == "HOSTED_DISPOSAL_TARGET_UNRESOLVED"));
    }

    [Theory]
    [InlineData("for-assignment", false)]
    [InlineData("while-ref", false)]
    [InlineData("do-local-function", false)]
    [InlineData("foreach-lambda", false)]
    [InlineData("backward-goto", false)]
    [InlineData("stable-for", true)]
    [InlineData("stable-goto", true)]
    [InlineData("uninvoked-local-function", true)]
    [InlineData("straight-line-later-write", true)]
    public void ExplicitAdmissionCleanupRequiresStableValueAcrossBackEdges(
        string shape,
        bool exact)
    {
        const string cleanup = "if (group is not null) group.Dispose();";

        string repeated = shape switch
        {
            "for-assignment" => "for (int iteration = 0; iteration < 2; iteration++) { " + cleanup + " group = new EffectfulCleanup(); }",
            "while-ref" => "while (token.CanBeCanceled) { " + cleanup + " AdmissionBackEdgeInput.Replace(ref group); }",
            "do-local-function" => "void Mutate() { group = new EffectfulCleanup(); } do { " + cleanup + " Mutate(); } while (token.CanBeCanceled);",
            "foreach-lambda" => "Action mutate = () => group = new EffectfulCleanup(); foreach (int iteration in new[] { 1, 2 }) { " + cleanup + " mutate(); }",
            "backward-goto" => "again: " + cleanup + " group = new EffectfulCleanup(); if (token.CanBeCanceled) goto again;",
            "stable-goto" => "again: " + cleanup + " if (token.CanBeCanceled) goto again;",
            "uninvoked-local-function" => "void Mutate() { group = new EffectfulCleanup(); } for (int iteration = 0; iteration < 2; iteration++) { " + cleanup + " }",
            "straight-line-later-write" => cleanup + " group = new EffectfulCleanup();",
            _ => "for (int iteration = 0; iteration < 2; iteration++) { " + cleanup + " }",
        };

        string source = R2Source(
            AcquireWork.Replace("return Task.CompletedTask;", "return;", StringComparison.Ordinal)
                + "IDisposable group = null!; if (!lease.TryBeginExternalEffectGroup(out group)) return;"
                + "System.IO.File.Exists(\"back-edge-traversal-witness\");" + repeated,
            "internal sealed class EffectfulCleanup : IDisposable { public void Dispose() { System.IO.File.Delete(\"replacement-cleanup-effect\"); } } "
                + "internal static class AdmissionBackEdgeInput { internal static void Replace(ref IDisposable value) { value = new EffectfulCleanup(); } }");

        CSharpCompilation compilation = Compile(source);

        Assert.Empty(compilation.GetDiagnostics().Where(static diagnostic =>
            diagnostic.Severity == DiagnosticSeverity.Error));

        HostedProducerDiscovery<HostedProducerSite> result = R2Discover(source);

        Assert.Single(result.Items, static site => site.Callee == "System.IO.File.Exists");

        bool unresolved = result.Diagnostics.Any(static diagnostic =>
            diagnostic.Code == "HOSTED_DISPOSAL_TARGET_UNRESOLVED");

        bool replacementEffect = result.Items.Any(static site => site.Callee == "System.IO.File.Delete");

        if (exact)
        {
            Assert.False(unresolved);

            Assert.False(replacementEffect);
        }
        else
        {
            Assert.True(unresolved || replacementEffect,
                "A replacement carried back to cleanup must be traversed or refused, never exempted as the original admission handle.");
        }
    }

    private const string AdmissionTypes = """
        namespace RetroDownfall.Arcanum.Infrastructure.Data
        {
            public enum GrimoireWorkKind { WorkspaceIndexing = 4 }
            public interface IGrimoireWorkLease : System.IDisposable, System.IAsyncDisposable { bool TryBeginExternalEffectGroup(out System.IDisposable group); }
            public interface IGrimoireConnectionAdmissionGate { bool TryAcquireWorkLease(GrimoireWorkKind kind, out IGrimoireWorkLease lease); }
        }
        """;

    private const string AcquireWork = "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate gate = null!; if (!gate.TryAcquireWorkLease(RetroDownfall.Arcanum.Infrastructure.Data.GrimoireWorkKind.WorkspaceIndexing, out var work)) return Task.CompletedTask; using var lease = work;";

    [Theory]
    [InlineData("immediate-finally", true)]
    [InlineData("actual-four-locals", true)]
    [InlineData("constant-default-locals", true)]
    [InlineData("throwing-call", false)]
    [InlineData("throwing-initializer", false)]
    [InlineData("early-disposal", false)]
    [InlineData("replaced-lease", false)]
    [InlineData("wrong-cleanup", false)]
    [InlineData("conditional-cleanup", false)]
    [InlineData("unawaited-cleanup", false)]
    [InlineData("nested-finally", true)]
    [InlineData("pre-lease-throwing-call", false)]
    [InlineData("cleanup-leading-throwing-call", false)]
    [InlineData("pre-lease-conversion", false)]
    [InlineData("pre-try-conversion", false)]
    [InlineData("pre-cleanup-conversion", false)]
    [InlineData("lease-downcast", false)]
    [InlineData("lease-replacement-before-read", false)]
    [InlineData("lease-replacement-before-cleanup", false)]
    [InlineData("conditional-expression-cleanup", false)]
    [InlineData("switch-expression-cleanup", false)]
    [InlineData("coalescing-expression-cleanup", false)]
    public void ManualWorkLeaseFinallyMayFollowOnlyNonThrowingPrelude(string shape, bool retained)
    {
        string prelude = shape switch
        {
            "actual-four-locals" => "IDisposable? group = null; Microsoft.Extensions.DependencyInjection.AsyncServiceScope scope = default; bool scopeCreated = false; long? refusedGeneration = null;",
            "constant-default-locals" => "object marker; int value = 7; CancellationToken cancellation = default(CancellationToken); ;",
            "throwing-call" => "MayThrow();",
            "throwing-initializer" => "object marker = MayThrow();",
            "pre-try-conversion" => "ThrowingToken marker = 7;",
            "early-disposal" => "await lease.DisposeAsync().ConfigureAwait(false);",
            "replaced-lease" => "lease = null!;",
            _ => string.Empty,
        };

        string cleanup = shape switch
        {
            "wrong-cleanup" => "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease wrong = null!; await wrong.DisposeAsync().ConfigureAwait(false);",
            "conditional-cleanup" => "if (token.IsCancellationRequested) await lease.DisposeAsync().ConfigureAwait(false);",
            "unawaited-cleanup" => "_ = lease.DisposeAsync();",
            "nested-finally" => "try { await Task.CompletedTask; } finally { await lease.DisposeAsync().ConfigureAwait(false); }",
            "cleanup-leading-throwing-call" => "MayThrow(); await lease.DisposeAsync().ConfigureAwait(false);",
            "pre-cleanup-conversion" => "ThrowingToken marker = 7; await lease.DisposeAsync().ConfigureAwait(false);",
            "lease-replacement-before-cleanup" => "lease = null!; await lease.DisposeAsync().ConfigureAwait(false);",
            "conditional-expression-cleanup" => "await (token.IsCancellationRequested ? lease.DisposeAsync() : ValueTask.CompletedTask);",
            "switch-expression-cleanup" => "await (token.IsCancellationRequested switch { true => lease.DisposeAsync(), false => ValueTask.CompletedTask });",
            "coalescing-expression-cleanup" => "await ((ValueTask?)default(ValueTask) ?? lease.DisposeAsync());",
            _ => "await lease.DisposeAsync().ConfigureAwait(false);",
        };

        string body = "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate gate = null!; "
            + "if (!gate.TryAcquireWorkLease(RetroDownfall.Arcanum.Infrastructure.Data.GrimoireWorkKind.WorkspaceIndexing, out var work)) return; "
            + (shape == "pre-lease-throwing-call" ? "MayThrow(); "
                : shape == "pre-lease-conversion" ? "ThrowingToken marker = 7; " : string.Empty)
            + (shape == "lease-downcast" ? "OtherLease lease = (OtherLease)work; "
                : "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease lease = work; ")
            + prelude
            + " try { "
            + (shape == "lease-replacement-before-read" ? "lease = null!; " : string.Empty)
            + "await Task.CompletedTask; _ = System.IO.File.Exists(\"manual-prelude-frontier\"); } finally { "
            + cleanup
            + " }";

        string source = "#nullable enable\n" + R2Source(body).Replace(
            "public async Task StartAsync",
            "private static object MayThrow() => throw new InvalidOperationException(); "
                + "private readonly struct ThrowingToken { public static implicit operator ThrowingToken(int value) => throw new InvalidOperationException(); } "
                + "private sealed class OtherLease : RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease { "
                + "public bool TryBeginExternalEffectGroup(out IDisposable group) { group = null!; return false; } "
                + "public void Dispose() { } public ValueTask DisposeAsync() => ValueTask.CompletedTask; } "
                + "public async Task StartAsync",
            StringComparison.Ordinal);

        CSharpCompilation compilation = Compile(source);

        Assert.Empty(compilation.GetDiagnostics().Where(static diagnostic => diagnostic.Severity == DiagnosticSeverity.Error));

        SyntaxTree tree = Assert.Single(compilation.SyntaxTrees);

        SemanticModel model = compilation.GetSemanticModel(tree);

        MethodDeclarationSyntax root = Assert.Single(tree.GetRoot().DescendantNodes().OfType<MethodDeclarationSyntax>(),
            static method => method.Identifier.ValueText == "StartAsync");

        InvocationExpressionSyntax acquisition = Assert.Single(root.DescendantNodes().OfType<InvocationExpressionSyntax>(),
            static call => call.Expression is MemberAccessExpressionSyntax { Name.Identifier.ValueText: "TryAcquireWorkLease" });

        var admitted = Assert.IsAssignableFrom<Microsoft.CodeAnalysis.Operations.IInvocationOperation>(model.GetOperation(acquisition));

        Assert.Equal("RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate", admitted.TargetMethod.ContainingType.ToDisplayString());

        VariableDeclaratorSyntax lease = Assert.Single(root.DescendantNodes().OfType<VariableDeclaratorSyntax>(),
            static variable => variable.Identifier.ValueText == "lease");

        if (shape == "lease-downcast")
        {
            CastExpressionSyntax cast = Assert.IsType<CastExpressionSyntax>(lease.Initializer!.Value);

            var conversion = Assert.IsAssignableFrom<Microsoft.CodeAnalysis.Operations.IConversionOperation>(model.GetOperation(cast));

            Assert.False(conversion.IsImplicit);

            Assert.True(conversion.Conversion.IsReference);

            Assert.Equal("work", Assert.IsAssignableFrom<Microsoft.CodeAnalysis.Operations.ILocalReferenceOperation>(conversion.Operand).Local.Name);
        }
        else Assert.Equal("work", Assert.IsType<IdentifierNameSyntax>(lease.Initializer!.Value).Identifier.ValueText);

        if (shape is "pre-lease-conversion" or "pre-try-conversion" or "pre-cleanup-conversion")
        {
            VariableDeclaratorSyntax marker = Assert.Single(root.DescendantNodes().OfType<VariableDeclaratorSyntax>(),
                static variable => variable.Identifier.ValueText == "marker");

            var initializer = Assert.IsAssignableFrom<Microsoft.CodeAnalysis.Operations.IVariableInitializerOperation>(model.GetOperation(marker.Initializer!));

            var conversion = Assert.IsAssignableFrom<Microsoft.CodeAnalysis.Operations.IConversionOperation>(initializer.Value);

            Assert.True(conversion.IsImplicit && conversion.Conversion.IsUserDefined);

            Assert.NotNull(conversion.OperatorMethod);

            Assert.Equal(compilation.Assembly.Identity, conversion.OperatorMethod!.ContainingAssembly.Identity);

            Assert.True(model.GetConstantValue(marker.Initializer!.Value).HasValue);
        }

        TryStatementSyntax protector = Assert.Single(root.DescendantNodes().OfType<TryStatementSyntax>(),
            candidate => candidate.Parent == root.Body);

        Assert.NotNull(protector.Finally);

        Assert.True(acquisition.Span.End < lease.SpanStart && lease.Span.End < protector.SpanStart);

        InvocationExpressionSyntax physicalRead = Assert.Single(protector.Block.DescendantNodes().OfType<InvocationExpressionSyntax>(),
            static call => call.Expression.ToString() == "System.IO.File.Exists");

        Assert.Equal("System.IO.File", Assert.IsAssignableFrom<IMethodSymbol>(model.GetSymbolInfo(physicalRead).Symbol).ContainingType.ToDisplayString());

        if (shape is "lease-replacement-before-read" or "lease-replacement-before-cleanup")
        {
            ILocalSymbol held = Assert.IsAssignableFrom<ILocalSymbol>(model.GetDeclaredSymbol(lease));

            AssignmentExpressionSyntax replacement = Assert.Single(root.DescendantNodes().OfType<AssignmentExpressionSyntax>(),
                assignment => SymbolEqualityComparer.Default.Equals(model.GetSymbolInfo(assignment.Left).Symbol, held));

            if (shape == "lease-replacement-before-read")
            {
                Assert.True(protector.Block.Span.Contains(replacement.Span));

                Assert.True(replacement.Span.End < physicalRead.SpanStart);
            }
            else
            {
                Assert.True(protector.Finally!.Block.Span.Contains(replacement.Span));

                InvocationExpressionSyntax cleanupCall = Assert.Single(protector.Finally.Block.DescendantNodes().OfType<InvocationExpressionSyntax>(),
                    call => call.Expression is MemberAccessExpressionSyntax { Name.Identifier.ValueText: "DisposeAsync" });

                Assert.True(replacement.Span.End < cleanupCall.SpanStart);
            }
        }

        if (shape is "conditional-expression-cleanup" or "switch-expression-cleanup" or "coalescing-expression-cleanup")
        {
            InvocationExpressionSyntax cleanupCall = Assert.Single(protector.Finally!.Block.DescendantNodes().OfType<InvocationExpressionSyntax>(),
                call => call.Expression is MemberAccessExpressionSyntax { Name.Identifier.ValueText: "DisposeAsync" });

            var invocation = Assert.IsAssignableFrom<Microsoft.CodeAnalysis.Operations.IInvocationOperation>(model.GetOperation(cleanupCall));

            Assert.Equal("System.IAsyncDisposable", invocation.TargetMethod.ContainingType.ToDisplayString());

            Assert.Equal("lease", Assert.IsAssignableFrom<Microsoft.CodeAnalysis.Operations.ILocalReferenceOperation>(invocation.Instance).Local.Name);

            Assert.Empty(invocation.Arguments);

            Assert.Single(protector.Finally.Block.DescendantNodes().OfType<AwaitExpressionSyntax>());

            if (shape == "conditional-expression-cleanup")
            {
                ConditionalExpressionSyntax choice = Assert.Single(protector.Finally.Block.DescendantNodes().OfType<ConditionalExpressionSyntax>());

                Assert.Equal(cleanupCall.Span, choice.WhenTrue.Span);

                Assert.Equal("ValueTask.CompletedTask", choice.WhenFalse.ToString());
            }
            else if (shape == "switch-expression-cleanup")
            {
                SwitchExpressionSyntax choice = Assert.Single(protector.Finally.Block.DescendantNodes().OfType<SwitchExpressionSyntax>());

                Assert.Equal(2, choice.Arms.Count);

                Assert.Equal(cleanupCall.Span, choice.Arms[0].Expression.Span);

                Assert.Equal("ValueTask.CompletedTask", choice.Arms[1].Expression.ToString());
            }
            else
            {
                BinaryExpressionSyntax choice = Assert.Single(protector.Finally.Block.DescendantNodes().OfType<BinaryExpressionSyntax>(),
                    expression => expression.IsKind(SyntaxKind.CoalesceExpression));

                Assert.Equal(cleanupCall.Span, choice.Right.Span);

                CastExpressionSyntax occupied = Assert.IsType<CastExpressionSyntax>(choice.Left);

                Assert.Equal("System.Threading.Tasks.ValueTask?", model.GetTypeInfo(occupied).Type!.ToDisplayString());

                Assert.IsType<DefaultExpressionSyntax>(occupied.Expression);
            }
        }

        HostedProducerDiscovery<HostedProducerSite> result = HostedGrimoireProducerInventory.DiscoverProducerSites(
            [compilation], new(["Worker"], []), [new("Worker", [OrdinaryRoot()])], []);

        HostedProducerSite acquired = Assert.Single(result.Items,
            static site => site.RootType == "Worker" && site.Callee == "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate.TryAcquireWorkLease");

        HostedProducerSite reached = Assert.Single(result.Items,
            static site => site.RootType == "Worker" && site.Callee == "System.IO.File.Exists");

        Assert.Equal(GrimoireWorkKind.WorkspaceIndexing, acquired.AdmittedWorkKind);

        output.WriteLine($"R196_MANUAL_PRELUDE_GUARDS={shape}|compilerAcquisitionFinallyAndRead=passed");

        if (retained)
        {
            Assert.Equal(acquired.CapsuleId, reached.WorkFrontierCapsuleId);
        }
        else
        {
            Assert.Null(reached.WorkFrontierCapsuleId);
        }
    }

    [Theory]
    [InlineData("{ using var lease = work; System.IO.File.Exists(\"path\"); }", true)]
    [InlineData("try { using var lease = work; System.IO.File.Exists(\"path\"); } finally { }", true)]
    [InlineData("object marker; { using var lease = work; System.IO.File.Exists(\"path\"); }", true)]
    [InlineData("{ using var lease = work; } System.IO.File.Exists(\"path\");", false)]
    [InlineData("if (DateTime.UtcNow.Ticks < 0) { using var lease = work; System.IO.File.Exists(\"path\"); }", false)]
    [InlineData("MayThrow(); { using var lease = work; System.IO.File.Exists(\"path\"); }", false)]
    public void NestedLexicalLeaseMustTakeOwnershipBeforeAnyThrowingPath(
        string lifetime,
        bool retained)
    {
        string acquire = "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate gate = null!; "
            + "if (!gate.TryAcquireWorkLease(RetroDownfall.Arcanum.Infrastructure.Data.GrimoireWorkKind.WorkspaceIndexing, out var work)) return; ";

        const string helper = "static void MayThrow() => throw new InvalidOperationException();";

        HostedProducerDiscovery<HostedProducerSite> result = R2Discover(
            R2Source(acquire + lifetime).Replace(
                "public async Task StartAsync",
                helper + " public async Task StartAsync",
                StringComparison.Ordinal));

        Assert.Equal(
            retained,
            !result.Diagnostics.Any(static diagnostic =>
                diagnostic.Code == "HOSTED_SITE_WORK_FRONTIER_MISSING"
                && diagnostic.Detail == "System.IO.File.Exists"));
    }

    [Theory]
    [InlineData("manual", true)]
    [InlineData("using", true)]
    [InlineData("alternative-return", false)]
    [InlineData("wrong-kind", false)]
    [InlineData("intervening-throw", false)]
    [InlineData("missing-cleanup", false)]
    [InlineData("conditional-cleanup", false)]
    [InlineData("unawaited", false)]
    public void ReturnedWorkLeaseRequiresExactAcquisitionAndExhaustiveCallerOwnership(
        string shape,
        bool retained)
    {
        string kind = shape == "wrong-kind"
            ? "(RetroDownfall.Arcanum.Infrastructure.Data.GrimoireWorkKind)0"
            : "RetroDownfall.Arcanum.Infrastructure.Data.GrimoireWorkKind.WorkspaceIndexing";

        string alternative = shape == "alternative-return"
            ? "if (DateTime.UtcNow.Ticks < 0) return new OtherLease();"
            : "";

        string body = shape switch
        {
            "using" => "using var lease = await AcquireAsync(gate); System.IO.File.Exists(\"path\");",
            "intervening-throw" => "var lease = await AcquireAsync(gate); MayThrow(); try { System.IO.File.Exists(\"path\"); } finally { lease.Dispose(); }",
            "missing-cleanup" => "var lease = await AcquireAsync(gate); System.IO.File.Exists(\"path\");",
            "conditional-cleanup" => "var lease = await AcquireAsync(gate); try { System.IO.File.Exists(\"path\"); } finally { if (DateTime.UtcNow.Ticks < 0) lease.Dispose(); }",
            "unawaited" => "Task<RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease> pending = AcquireAsync(gate); System.IO.File.Exists(\"path\"); await pending;",
            _ => "var lease = await AcquireAsync(gate); try { System.IO.File.Exists(\"path\"); } finally { lease.Dispose(); }",
        };

        string members = "private sealed class OtherLease : RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease { "
            + "public bool TryBeginExternalEffectGroup(out IDisposable group) { group = null!; return false; } "
            + "public void Dispose() { } public ValueTask DisposeAsync() => ValueTask.CompletedTask; } "
            + "private static void MayThrow() => throw new InvalidOperationException(); "
            + "private static async Task<RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease> AcquireAsync("
            + "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate gate) { await Task.Yield(); "
            + alternative
            + " if (gate.TryAcquireWorkLease(" + kind + ", out var lease)) { return lease; } throw new OperationCanceledException(); } ";

        string source = R2Source(
                "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate gate = null!; "
                + body)
            .Replace(
                "public async Task StartAsync",
                members + " public async Task StartAsync",
                StringComparison.Ordinal);

        HostedProducerDiscovery<HostedProducerSite> result = R2Discover(source);

        Assert.Equal(
            retained,
            !result.Diagnostics.Any(static diagnostic =>
                diagnostic.Code == "HOSTED_SITE_WORK_FRONTIER_MISSING"
                && diagnostic.Detail == "System.IO.File.Exists"));
    }

    [Fact]
    public void CompoundFailureGuardDominatesTheRetainedWorkFrontier()
    {
        const string body = "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate gate = null!; if (DateTime.UtcNow.Ticks < 0 || !gate.TryAcquireWorkLease(RetroDownfall.Arcanum.Infrastructure.Data.GrimoireWorkKind.WorkspaceIndexing, out var work)) return Task.CompletedTask; using var lease = work; System.IO.File.Exists(\"path\");";

        HostedProducerDiscovery<HostedProducerSite> result = DiscoverWithRoots(FixtureSource(body, AdmissionTypes), OrdinaryRoot());

        Assert.DoesNotContain(result.Diagnostics, static diagnostic => diagnostic.Code == "HOSTED_SITE_WORK_FRONTIER_MISSING");

        Assert.Contains(result.Items, static site => site.Kind == HostedProducerSiteKind.EffectFrontier && site.Callee.EndsWith(".TryAcquireWorkLease", StringComparison.Ordinal));
    }

    [Fact]
    public void SoleSuccessfulLoopExitDominatesTheRetainedWorkFrontier()
    {
        const string body = "RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate gate = null!; RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease work; while (true) { if (gate.TryAcquireWorkLease(RetroDownfall.Arcanum.Infrastructure.Data.GrimoireWorkKind.WorkspaceIndexing, out work)) { break; } } using var lease = work; System.IO.File.Exists(\"path\");";

        HostedProducerDiscovery<HostedProducerSite> result = DiscoverWithRoots(FixtureSource(body, AdmissionTypes), OrdinaryRoot());

        Assert.DoesNotContain(result.Diagnostics, static diagnostic => diagnostic.Code == "HOSTED_SITE_WORK_FRONTIER_MISSING");

        Assert.Contains(result.Items, static site => site.Kind == HostedProducerSiteKind.EffectFrontier && site.Callee.EndsWith(".TryAcquireWorkLease", StringComparison.Ordinal));
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void R2DeclaredAuthorityDoesNotOverrideTheCallingAuthority(bool admitted)
    {
        string source = R2Source((admitted ? R2Admission : "") + "await ContinueAsync(token);").Replace("public Task StopAsync", "private Task ContinueAsync(CancellationToken token) { System.IO.File.Delete(\"path\"); return Task.CompletedTask; } public Task StopAsync", StringComparison.Ordinal);

        HostedProducerOperationEntry startup = OrdinaryRoot("Worker.ContinueAsync") with { Member = "ContinueAsync", Authority = HostedProducerAuthorityKind.PreReadinessStartup, WorkKind = null, Proof = "Worker.ContinueAsync: readiness" };

        HostedProducerDiscovery<HostedProducerSite> discovery = R2Discover(source, OrdinaryRoot(), startup);

        Assert.Equal(2, discovery.Items.Count(static site => site.Callee == "System.IO.File.Delete"));

        Assert.Equal(admitted, !discovery.Diagnostics.Any(static diagnostic => diagnostic.Code == "HOSTED_SITE_WORK_FRONTIER_MISSING"));

        Assert.Contains(
            discovery.Items,
            static site => site.Callee == "System.IO.File.Delete"
                && site.Member == "ContinueAsync"
                && site.OperationId.StartsWith("Worker.StartAsync/", StringComparison.Ordinal));
    }

    [Theory]
    [InlineData("", false)]
    [InlineData("if (background is not null) await background.WaitAsync(token);", true)]
    [InlineData("if (DateTime.UtcNow.Ticks < 0) await background!;", false)]
    public void R2HostHandoffRequiresAnExactTaskFieldAndStopJoin(string stopBody, bool joined)
    {
        string source = R2Source("background = Task.Run(() => ContinueAsync(token));")
            .Replace("public Task StopAsync(CancellationToken token) => Task.CompletedTask;", "private Task? background; private async Task ContinueAsync(CancellationToken token) { " + R2Admission + " System.IO.File.Delete(\"path\"); } public async Task StopAsync(CancellationToken token) { " + stopBody + " }", StringComparison.Ordinal);

        HostedProducerOperationEntry startup = OrdinaryRoot() with { Authority = HostedProducerAuthorityKind.PreReadinessStartup, WorkKind = null, Proof = "Worker.StartAsync: readiness" };

        HostedProducerOperationEntry runtime = OrdinaryRoot("Worker.ContinueAsync") with { Member = "ContinueAsync" };

        HostedProducerDiscovery<HostedProducerSite> discovery = R2Discover(source, startup, runtime);

        Assert.Equal(joined, !discovery.Diagnostics.Any(static diagnostic => diagnostic.Code == "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN"));

        Assert.Equal(joined ? 1 : 2, discovery.Items.Count(static site => site.Callee == "System.IO.File.Delete"));

        if (joined)
        {
            Assert.DoesNotContain(discovery.Diagnostics, static diagnostic => diagnostic.Code is "HOSTED_SITE_WORK_FRONTIER_MISSING" or "HOSTED_SITE_EFFECT_FRONTIER_MISSING");
        }
    }

