                [],
                roots.Select(method => new NonHostedProducerChainEntry(
                    target + "." + method,
                    "src/Fixture.cs",
                    target,
                    method,
                    HostedProducerAuthorityKind.PreReadinessStartup,
                    "recovery membership order fixture",
