    [Fact]
    public void RepeatedExactBoundValueNormalizationBuildsOncePerImmutableSource()
    {
        string calls = string.Join(
            " ",
            Enumerable.Repeat(
                "RepeatedNormalizationTarget.Route(stream);",
                16));

        const string helper =
            "internal static class RepeatedNormalizationTarget { "
            + "internal static void Route(System.IO.Stream stream) { "
            + "using System.IO.StreamReader reader = new(stream, System.Text.Encoding.UTF8, true, 1024, leaveOpen: true); _ = reader.ReadToEnd(); } }";

        HostedProducerDiscovery<HostedProducerSite> result = Discover(
            FixtureSource(
                "using System.IO.Stream stream = System.IO.File.OpenRead(\"normalization-cache\"); "
                    + calls,
                helper));

        Assert.Contains(result.Items, static site =>
            site.EnclosingType == "RepeatedNormalizationTarget"
            && site.Callee == "System.IO.StreamReader.ReadToEnd");

        HostedProducerAnalysisMetrics metrics =
            Assert.IsType<HostedProducerAnalysisMetrics>(result.AnalysisMetrics);

        int requests = metrics.EvaluationEnvironments.Sum(
            static metric => metric.ValueNormalizationRequests);

        int builds = metrics.EvaluationEnvironments.Sum(
            static metric => metric.ValueNormalizationBuilds);

        int hits = metrics.EvaluationEnvironments.Sum(
            static metric => metric.ValueNormalizationHits);

        Assert.True(requests >= 16);

        Assert.True(
            builds < requests,
            $"requests={requests}, builds={builds}, hits={hits}");

        Assert.Equal(requests - builds, hits);
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void RepeatedResultPropertyCleanupKeepsUnchangedProjectionWorkBounded(bool emptyEnvironment)
    {
        const int calls = 16;

        string body = "IProjectedCleanup cleanup = new ProjectedCleanup(); "
            + string.Join(" ", Enumerable.Repeat("await ProjectedCleanupPipeline.RunAsync(cleanup);", calls));

        const string helper =
            "internal interface IProjectedCleanup : System.IAsyncDisposable { } "
            + "internal sealed class ProjectedCleanup : IProjectedCleanup { public System.Threading.Tasks.ValueTask DisposeAsync() { System.IO.File.Exists(\"projection-cleanup\"); return default; } } "
            + "internal sealed class ProjectedResult<T> { private readonly T value; private ProjectedResult(T value) { this.value = value; } internal T Value => value; internal static ProjectedResult<T> Success(T value) => new(value); } "
            + "internal static class ProjectedCleanupPipeline { internal static async System.Threading.Tasks.Task RunAsync(IProjectedCleanup cleanup) { ProjectedResult<IProjectedCleanup> first = Wrap(cleanup); ProjectedResult<IProjectedCleanup> second = Wrap(first.Value); ProjectedResult<IProjectedCleanup> third = Wrap(second.Value); await using (third.Value) { await System.Threading.Tasks.Task.Yield(); } } private static ProjectedResult<IProjectedCleanup> Wrap(IProjectedCleanup cleanup) => ProjectedResult<IProjectedCleanup>.Success(cleanup); private static ProjectedResult<IProjectedCleanup> Empty() => ProjectedResult<IProjectedCleanup>.Success(new ProjectedCleanup()); }";

        string source = R2Source(body, helper);

        if (emptyEnvironment)
        {
            source = source.Replace("first = Wrap(cleanup)", "first = Empty()", StringComparison.Ordinal);
        }

        CSharpCompilation compilation = Compile(source);

        MethodDeclarationSyntax method = compilation.SyntaxTrees.Single().GetRoot()
            .DescendantNodes().OfType<MethodDeclarationSyntax>()
            .Single(candidate => candidate.Identifier.ValueText == (emptyEnvironment ? "Empty" : "Wrap"));

        IMethodSymbol sourceMethod = Assert.IsAssignableFrom<IMethodSymbol>(compilation.GetSemanticModel(method.SyntaxTree).GetDeclaredSymbol(method));

        ExpressionSyntax sourceExpression = Assert.IsType<InvocationExpressionSyntax>(method.ExpressionBody!.Expression).ArgumentList.Arguments.Single().Expression;

        var probe = HostedGrimoireProducerInventory.ProbeRepeatedExactSourceProjection(
            compilation,
            OrdinaryRoot() with
            {
                Authority = HostedProducerAuthorityKind.PreReadinessStartup,
                WorkKind = null,
                Proof = "Worker.StartAsync: repeated exact result cleanup projection",
            },
            sourceMethod,
            sourceExpression,
            calls);

        HostedProducerDiscovery<HostedProducerSite> result = probe.Discovery;

        Assert.Empty(result.Diagnostics);

        Assert.Contains(result.Items, static site =>
            site.EnclosingType == "ProjectedCleanup"
            && site.Callee == "System.IO.File.Exists");

        Assert.True(probe.Complete);

        Assert.Equal(1, probe.DistinctFingerprints);

        output.WriteLine($"Repeated result cleanup work: normalizations={probe.NormalizationBuilds}; fingerprints={probe.FingerprintBuilds}");

        Assert.InRange(probe.NormalizationBuilds, 0, 1);

        Assert.InRange(probe.FingerprintBuilds, 0, 1);
    }

    [Fact]
    public void RepeatedPartialResultCleanupProjectionKeepsPhysicalIdentityWorkBounded()
    {
        CSharpCompilation compilation = Compile(PartialResultCleanupProjectionSource(unknownInput: false));

        Assert.Empty(compilation.GetDiagnostics().Where(static diagnostic => diagnostic.Severity == DiagnosticSeverity.Error));

        MethodDeclarationSyntax method = compilation.SyntaxTrees.Single().GetRoot()
            .DescendantNodes().OfType<MethodDeclarationSyntax>()
            .Single(static candidate => candidate.Identifier.ValueText == "Wrap");

        IMethodSymbol sourceMethod = Assert.IsAssignableFrom<IMethodSymbol>(
            compilation.GetSemanticModel(method.SyntaxTree).GetDeclaredSymbol(method));

        ReturnStatementSyntax returned = Assert.Single(method.Body!.Statements.OfType<ReturnStatementSyntax>());

        ExpressionSyntax expression = Assert.IsType<InvocationExpressionSyntax>(returned.Expression)
            .ArgumentList.Arguments.Single().Expression;

        HostedProducerPartialProjectionProbe probe = HostedGrimoireProducerInventory.ProbeRepeatedPartialSourceProjection(
            compilation,
            OrdinaryRoot() with
            {
                Authority = HostedProducerAuthorityKind.PreReadinessStartup,
                WorkKind = null,
                Proof = "Worker.StartAsync: repeated nonempty partial cleanup projection",
            },
            sourceMethod,
            expression,
            16);

        output.WriteLine($"Partial projection: builds={probe.ProjectionBuilds}; tokenIdentityBuilds={probe.TokenIdentityBuilds}; exactTokenInputs={probe.ExactTokenInputs}; nullTokens={probe.NullTokens}; distinctTokens={probe.DistinctTokens}; original={probe.OriginalBindings}; retained={string.Join(";", probe.RetainedBindings)}");

        Assert.Empty(probe.Discovery.Diagnostics);

        Assert.Contains(probe.Discovery.Items, static site =>
            site.EnclosingType == "PartialCleanup"
            && site.Member == "Dispose"
            && site.Callee == "System.IO.File.Exists");

        Assert.Contains(probe.Discovery.Items, static site =>
            site.EnclosingType == "PartialUnusedCleanup"
            && site.Member == "Dispose"
            && site.Callee == "System.IO.File.Delete");

        Assert.Equal("cleanup,unused", probe.OriginalBindings);

        Assert.Equal(16, probe.RetainedBindings.Count);

        Assert.All(probe.RetainedBindings, static keys => Assert.Equal("cleanup", keys));

        Assert.True(probe.ContextsPreserved);

        Assert.Equal(0, probe.NullTokens);

        Assert.Equal(1, probe.DistinctTokens);

        // Desired bounded-work contract, not a claimed observation: run RED before any repair.
        Assert.InRange(probe.ProjectionBuilds, 0, 1);

        Assert.InRange(probe.TokenIdentityBuilds, 0, 1);
    }

    [Theory]
    [InlineData("ExplicitCleanupForwarder.Close(new ExplicitCleanup());", false, false)]
    [InlineData("IExplicitCleanup value = new ExplicitCleanup(); ExplicitCleanupForwarder.Close(value);", false, false)]
    [InlineData("IDisposable value = new ExplicitCleanup(); value.Dispose();", false, false)]
    [InlineData("await ExplicitCleanupForwarder.CloseAsync(new ExplicitCleanup());", true, false)]
    [InlineData("IExplicitCleanup value = new ExplicitCleanup(); await ExplicitCleanupForwarder.CloseAsync(value);", true, false)]
    [InlineData("IAsyncDisposable value = new ExplicitCleanup(); await value.DisposeAsync().ConfigureAwait(false);", true, false)]
    [InlineData("IExplicitCleanup value = new ExplicitCleanup(); value.DisposeAsync();", true, true)]
    [InlineData("IDisposable value = new SplitExplicitCleanup(); value.Dispose();", false, false)]
    public void ExplicitFrameworkCleanupPreservesExactReceiverEffects(string body, bool asynchronous, bool detached)
    {
        string source = R2Source(body, ExplicitFrameworkCleanupHelpers);

        Assert.Empty(Compile(source).GetDiagnostics().Where(static diagnostic => diagnostic.Severity == DiagnosticSeverity.Error));

        HostedProducerDiscovery<HostedProducerSite> result = DiscoverWithRoots(source,
            OrdinaryRoot() with { Authority = HostedProducerAuthorityKind.PreReadinessStartup, WorkKind = null });

        Assert.Contains(result.Items, site => site.Callee == (asynchronous ? "System.IO.File.Exists" : "System.IO.File.Delete"));

        if (body.Contains("SplitExplicitCleanup", StringComparison.Ordinal))
        {
            Assert.DoesNotContain(result.Items, static site => site.Callee == "System.IO.File.Exists");
        }

        Assert.Equal(detached, result.Diagnostics.Any(static diagnostic => diagnostic.Code == "HOSTED_CALLBACK_OWNERSHIP_UNPROVEN"));

        if (!detached)
        {
            Assert.Empty(result.Diagnostics);
        }
    }

