            });

        Assert.Contains(result.Diagnostics, static diagnostic =>
            diagnostic.Code == "HOSTED_DISPOSAL_TARGET_UNRESOLVED");

        Assert.Contains(result.Items, static site =>
            site.EnclosingType == "PartialUnusedCleanup"
            && site.Member == "Dispose"
            && site.Callee == "System.IO.File.Delete");
    }

    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void PartialCleanupProjectionKeepsReboundKnownAndUnknownInputsSeparate(bool unknownFirst)
    {
        string known = "PartialProjectionPipeline.Run(cleanup, unused);";

        string unknown = "PartialProjectionPipeline.Run(PartialProjectionInputs.Unknown(), unused);";

        string source = PartialResultCleanupProjectionSource(unknownInput: false)
            .Replace(known, unknownFirst ? unknown + known : known + unknown, StringComparison.Ordinal);

        Assert.Empty(Compile(source).GetDiagnostics().Where(static diagnostic => diagnostic.Severity == DiagnosticSeverity.Error));

        HostedProducerDiscovery<HostedProducerSite> result = DiscoverWithRoots(source,
            OrdinaryRoot() with { Authority = HostedProducerAuthorityKind.PreReadinessStartup, WorkKind = null });

        Assert.Contains(result.Diagnostics, static diagnostic => diagnostic.Code == "HOSTED_DISPOSAL_TARGET_UNRESOLVED");

        Assert.Contains(result.Items, static site => site.EnclosingType == "PartialCleanup" && site.Callee == "System.IO.File.Exists");

        Assert.Contains(result.Items, static site => site.EnclosingType == "PartialUnusedCleanup" && site.Callee == "System.IO.File.Delete");

        // A subsequent independent graph must neither inherit a failure nor an exact cleanup proof.
        HostedProducerDiscovery<HostedProducerSite> cold = DiscoverWithRoots(PartialResultCleanupProjectionSource(unknownInput: false),
            OrdinaryRoot() with { Authority = HostedProducerAuthorityKind.PreReadinessStartup, WorkKind = null });

        Assert.Empty(cold.Diagnostics);

        Assert.Contains(cold.Items, static site => site.EnclosingType == "PartialCleanup" && site.Callee == "System.IO.File.Exists");
    }

    private static string PartialResultCleanupProjectionSource(bool unknownInput)
    {
        string body = "IPartialCleanup cleanup = "
            + (unknownInput ? "PartialProjectionInputs.Unknown()" : "new PartialCleanup()")
            + "; IPartialCleanup unused = new PartialUnusedCleanup(); PartialProjectionPipeline.Run(cleanup, unused);";

        const string helper = """
            internal interface IPartialCleanup : System.IDisposable { }
            internal sealed class PartialCleanup : IPartialCleanup
            {
                public void Dispose() => System.IO.File.Exists("retained-partial-cleanup");
            }

            internal sealed class PartialUnusedCleanup : IPartialCleanup
            {
                public void Dispose() => System.IO.File.Delete("unused-partial-cleanup");
            }

            internal sealed class PartialProjectedResult<T>
            {
                private readonly T value;
                private PartialProjectedResult(T value) { this.value = value; }
                internal T Value => value;
                internal static PartialProjectedResult<T> Success(T value) => new(value);
            }

            internal static class PartialProjectionInputs
            {
                internal static extern IPartialCleanup Unknown();
            }

            internal static class PartialProjectionPipeline
            {
                internal static void Run(IPartialCleanup cleanup, IPartialCleanup unused)
                {
                    PartialProjectedResult<IPartialCleanup> first = Wrap(cleanup, unused);
                    PartialProjectedResult<IPartialCleanup> second = Wrap(first.Value, unused);
                    PartialProjectedResult<IPartialCleanup> third = Wrap(second.Value, unused);
                    using (third.Value) { }
                }

                private static PartialProjectedResult<IPartialCleanup> Wrap(IPartialCleanup cleanup, IPartialCleanup unused)
                {
                    using (unused) { }
                    return PartialProjectedResult<IPartialCleanup>.Success(cleanup);
                }
            }
            """;

        return R2Source(body, helper);
    }

    [Fact]
    public void DivergentNestedCallableEnvironmentsCertifyDistinctTraversalTokens()
    {
        string calls = string.Join(
            " ",
            Enumerable.Repeat(
                    "DivergentCallableCacheTarget.Route(DivergentCallableCacheTarget.Read);",
                    16)
                .Concat(Enumerable.Repeat(
                    "DivergentCallableCacheTarget.Route(DivergentCallableCacheTarget.Delete);",
                    16)));

        const string helper =
            "internal static class DivergentCallableCacheTarget { "
            + "internal static void Route(System.Action callback) => callback(); "
            + "internal static void Read() => "
            + "System.IO.File.Exists(\"nested-read\"); "
            + "internal static void Delete() => "
            + "System.IO.File.Delete(\"nested-delete\"); }";

        HostedProducerDiscovery<HostedProducerSite> result = DiscoverWithRoots(
            R2Source(calls, helper),
            OrdinaryRoot() with
            {
                Authority = HostedProducerAuthorityKind.PreReadinessStartup,
                WorkKind = null,
                Proof = "Worker.StartAsync: divergent callable cache fixture",
            });

        Assert.Contains(result.Items, static site =>
            site.EnclosingType == "DivergentCallableCacheTarget"
            && site.Member == "Read"
            && site.Callee == "System.IO.File.Exists");

        Assert.Contains(result.Items, static site =>
            site.EnclosingType == "DivergentCallableCacheTarget"
            && site.Member == "Delete"
            && site.Callee == "System.IO.File.Delete");

        Assert.DoesNotContain(result.Diagnostics, static diagnostic => diagnostic.Code is "HOSTED_ROOT_UNRESOLVED" or "HOSTED_CALL_TARGET_UNRESOLVED" or "HOSTED_TRAVERSAL_STATE_LIMIT_EXCEEDED" or "HOSTED_EVALUATION_ENVIRONMENT_LIMIT_EXCEEDED");

        Assert.Equal(2, Assert.Single(result.AnalysisMetrics!.RootTraversals, static root => root.RootOperation == "Worker.StartAsync").TraversalCalls);

        HostedProducerEvaluationEnvironmentMetric metric = Assert.Single(
            Assert.IsType<HostedProducerAnalysisMetrics>(result.AnalysisMetrics)
                .EvaluationEnvironments,
            static candidate => candidate.Member.StartsWith(
                "M:DivergentCallableCacheTarget.Route(",
                StringComparison.Ordinal));

        Assert.Equal(2, metric.FingerprintRequests);

        Assert.Equal(2, metric.FingerprintBuilds);

        Assert.Equal(2, metric.EquivalentKeyBuilds);

        Assert.Equal(4, metric.EquivalentKeyNodes);

        Assert.Equal(64, metric.InternerRequests);

        Assert.Equal(32, metric.InternerIdentityBuilds);

        Assert.Equal(62, metric.InternerHits);

        Assert.Equal(2, metric.InternerRegistrations);
    }

    [Fact]
    public void StableLocalUseSitesConvergeBeforeTraversalStateIdentity()
    {
        string calls = string.Join(
            " ",
            Enumerable.Repeat(
                "StableLocalUseTarget.Read(stream);",
                32));

        const string helper =
            "internal static class StableLocalUseTarget { "
            + "internal static void Read(System.IO.Stream stream) { "
            + "_ = stream.CanRead; System.IO.File.Exists(\"stable-local-tail\"); } }";

        CSharpCompilation compilation = Compile(
            FixtureSource(
                "using System.IO.Stream stream = System.IO.File.OpenRead(\"stable-local\"); "
                    + calls,
                helper));

        HostedProducerDiscovery<HostedProducerSite> result =
            HostedGrimoireProducerInventory.DiscoverProducerSites(
                [compilation],
                new(["Worker"], []),
                [new("Worker", [OrdinaryRoot() with
                {
                    Authority = HostedProducerAuthorityKind.PreReadinessStartup,
                    WorkKind = null,
                    Proof = "Worker.StartAsync: stable local use-site fixture",
                }])],
                [],
                maximumAnalyzedStatesPerRoot: 16);

        Assert.Contains(result.Items, static site =>
            site.EnclosingType == "StableLocalUseTarget"
            && site.Member == "Read"
            && site.Callee == "System.IO.File.Exists");

        Assert.DoesNotContain(result.Diagnostics, static diagnostic =>
            diagnostic.Code == "HOSTED_TRAVERSAL_STATE_LIMIT_EXCEEDED");

        HostedProducerEvaluationEnvironmentMetric metric = Assert.Single(
            Assert.IsType<HostedProducerAnalysisMetrics>(result.AnalysisMetrics)
                .EvaluationEnvironments,
            static candidate => candidate.Member.StartsWith(
                "M:StableLocalUseTarget.Read(",
                StringComparison.Ordinal));

        Assert.Equal(1, metric.InternerRegistrations);

        HostedProducerEvaluationEnvironmentMetric sourceMetric = Assert.Single(
            Assert.IsType<HostedProducerAnalysisMetrics>(result.AnalysisMetrics)
                .EvaluationEnvironments,
            static candidate => candidate.Member.StartsWith(
                "M:Worker.StartAsync(",
                StringComparison.Ordinal));

        Assert.Equal(32, sourceMetric.StableLocalProofBuilds);

        string metrics = $"Stable local requests/builds/hits: {sourceMetric.StableLocalProofRequests}/{sourceMetric.StableLocalProofBuilds}/{sourceMetric.StableLocalProofHits}; normalization: {sourceMetric.ValueNormalizationRequests}/{sourceMetric.ValueNormalizationBuilds}/{sourceMetric.ValueNormalizationHits}; target interner requests/hits/registrations: {metric.InternerRequests}/{metric.InternerHits}/{metric.InternerRegistrations}";

        Assert.True(
            sourceMetric.StableLocalProofHits
                + sourceMetric.ValueNormalizationHits > 0,
            metrics);

        Assert.Equal(
            sourceMetric.StableLocalProofRequests
                - sourceMetric.StableLocalProofBuilds,
            sourceMetric.StableLocalProofHits);

        Assert.Equal(
            sourceMetric.ValueNormalizationRequests
                - sourceMetric.ValueNormalizationBuilds,
            sourceMetric.ValueNormalizationHits);
    }

