            {
                internal static Microsoft.Data.Sqlite.SqliteTransaction Value { get; set; } = null!;
            }
            """;

        HostedProducerDiscovery<HostedProducerSite> result = R2Discover(
            R2Source(R2Admission + body, helpers));

