                && diagnostic.Detail == "System.IO.StreamReader.ReadToEnd");

        HostedProducerDiscovery<HostedProducerSite> file = Discover(
            FixtureSource(
                "using System.IO.Stream stream = System.IO.File.OpenRead(\"path\"); _ = Read(stream);",
                helper));

        Assert.Contains(
