                diagnostic.Code == "HOSTED_DISPOSAL_TARGET_UNRESOLVED"));

        Assert.Equal(
            resolved,
            result.Items.Any(static site =>
                site.Callee == "System.IO.File.Delete"
                    && site.EffectFrontierCapsuleId is not null));
    }

    [Theory]
    [InlineData("true", true)]
    [InlineData("false", false)]
