    private static string ApprenticeSelfHandoffSource(string mutation)
    {
        string barrier = mutation == "missing-publication-barrier"
            ? string.Empty
            : "lock (_executionLifecycleLock) { }";

        string cleanupTask = mutation == "wrong-cleanup-task"
            ? "Task.CompletedTask"
            : "task!";

        string publishedTask = mutation == "wrong-published-task"
            ? "Task.CompletedTask"
            : "task";

        string catchClause = mutation == "missing-fault-observation"
            ? string.Empty
            : "catch (Exception) { }";

        return $$"""
            using System;
            using System.Collections.Generic;
            using System.Threading;
            using System.Threading.Tasks;
            using Microsoft.Extensions.Hosting;

            namespace RetroDownfall.Arcanum.Infrastructure.Hosting
            {
                public sealed class ApprenticeService : IHostedService
                {
                    private readonly object _executionLifecycleLock = new();
                    private readonly Dictionary<Guid, Task> _activeTasks = new();

                    public Task StartAsync(CancellationToken token)
                    {
                        BeginExecutionTask(Guid.Empty);

                        return Task.CompletedTask;
                    }

                    public Task StopAsync(CancellationToken token) => Task.CompletedTask;

                    private void BeginExecutionTask(Guid apprenticeId)
                    {
                        Task? task = null;

                        long generation = 1;

                        lock (_executionLifecycleLock)
                        {
                            task = Task.Run(async () =>
                            {
                                {{barrier}}

                                try
                                {
                                    await RunApprenticeAsync(apprenticeId, generation).ConfigureAwait(false);
                                }
                                {{catchClause}}
                                finally
                                {
                                    CleanupExecution(apprenticeId, generation, {{cleanupTask}});
                                }
                            });

                            _activeTasks[apprenticeId] = {{publishedTask}};
                        }
                    }

                    private static void CleanupExecution(
                        Guid apprenticeId,
                        long generation,
                        Task completedTask)
                    {
                    }

                    private static async Task RunApprenticeAsync(
                        Guid apprenticeId,
                        long generation)
                    {
                        RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireConnectionAdmissionGate gate = null!;

                        if (!gate.TryAcquireWorkLease(
                                RetroDownfall.Arcanum.Infrastructure.Data.GrimoireWorkKind.ApprenticeExecution,
                                out RetroDownfall.Arcanum.Infrastructure.Data.IGrimoireWorkLease lease))
                        {
                            return;
                        }

                        using (lease)
                        {
                            _ = System.IO.File.Exists("path");
                        }

                        await Task.CompletedTask;
                    }
                }
            }

            namespace RetroDownfall.Arcanum.Infrastructure.Data
            {
                public enum GrimoireWorkKind { ApprenticeExecution = 9 }

                public interface IGrimoireWorkLease : IDisposable
                {
                    bool TryBeginExternalEffectGroup(out IDisposable group);
                }

                public interface IGrimoireConnectionAdmissionGate
                {
                    bool TryAcquireWorkLease(
                        GrimoireWorkKind kind,
                        out IGrimoireWorkLease lease);
                }
            }
            """;
    }

    [Fact]
    public void Fixture_compilations_reuse_platform_metadata_without_sharing_source_symbols()
    {
        CSharpCompilation first = Compile("public sealed class FirstFixture { }");

        CSharpCompilation second = Compile("public sealed class SecondFixture { }");

        Assert.Empty(first.GetDiagnostics());

        Assert.Empty(second.GetDiagnostics());

        Assert.NotNull(first.GetTypeByMetadataName("FirstFixture"));

        Assert.Null(first.GetTypeByMetadataName("SecondFixture"));

        Assert.NotNull(second.GetTypeByMetadataName("SecondFixture"));

        Assert.Null(second.GetTypeByMetadataName("FirstFixture"));

        MetadataReference[] firstReferences = first.References.ToArray();

        MetadataReference[] secondReferences = second.References.ToArray();

        Assert.NotEmpty(firstReferences);

        Assert.Equal(firstReferences.Length, secondReferences.Length);

        for (int index = 0; index < firstReferences.Length; index++)
        {
            // Reference reuse bounds native PE metadata to one copy per platform assembly,
            // rather than one complete platform image set for every adversarial fixture.
            Assert.Same(firstReferences[index], secondReferences[index]);
        }
    }

    private static readonly Lazy<ImmutableArray<PortableExecutableReference>> FixturePlatformReferences = new(
        static () => ((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")!)
            .Split(Path.PathSeparator)
            .Select(static path => MetadataReference.CreateFromFile(path))
            .ToImmutableArray());

    private static CSharpCompilation Compile(string source) =>
        CSharpCompilation.Create(
            "InventoryFixture",
            [CSharpSyntaxTree.ParseText(source, path: "src/Fixture.cs")],
            FixturePlatformReferences.Value,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

    private static CSharpCompilation CompileWithProductionReferencePack(
        string source,
        string assemblyName = "RetroDownfall.Arcanum.Core")
    {
        CSharpCompilation referenceCompilation = HostedGrimoireProducerInventory
            .ProductionCompilations
            .Single(compilation => compilation.AssemblyName == assemblyName);

        return CSharpCompilation.Create(
            "InventoryReferencePackFixture",
            [CSharpSyntaxTree.ParseText(source, path: "src/Fixture.cs")],
            referenceCompilation.References,
            new CSharpCompilationOptions(
                OutputKind.DynamicallyLinkedLibrary));
    }
}

internal static class SdkFixtureTextMutation
{
    internal static string ReplaceSdkFixtureText(this string text, string previous, string replacement, StringComparison comparison)
    {
        Assert.Contains(previous, text, comparison);

        string changed = text.Replace(previous, replacement, comparison);

        Assert.NotEqual(text, changed);

        return changed;
    }
}
